# 22t_rdbyi_final.R  As 22_rdbyi_final.R with PSP thinning removals censored (the earlier frames counted thinned stems as deaths). Adopted by Aaron on November 11, 2026 (question tool) against the outcome of the PREREG rule, which is logged as such:
#   S1   SDImax = exp(s0 + s1 ln(BYI) + s2 planted), weighted second stage on the plot brms SDImax (RI_LONG of record)
#   E4r  dDBH = exp(b0 + b1 ln(DBH + 1) + b2 DBH + b3 (BAL / BA) RD + b4 ln(BYI) + b5 planted),  RD = SDI of live koa / SDImax from S1
#   E6r  annual P(death) = 1 - exp(-exp(c0 + c1 ln(DBH + 1) + c2 DBH + c3 DBH^2 + c4 BAL + c5 ln(RD) + c6 ln(BYI) + c7 planted))
# Parts: (1) fits and held-out increment error with S1 refitted in each fold; (2) interval components; (3) joint plot-cluster bootstrap in which
# every resample refits S1, then E4r and E6r with that resample's SDImax (E6r by direct maximum likelihood, as in 15d); (4) coefficient table and
# check of the reference file. No plot or installation identifier is printed.
suppressMessages({library(data.table)}); setwd("~/jobs/koa_final_eq_20261110"); source("scripts/utils.R"); source("release/koa_step.R"); options(width = 230)
NB <- as.integer(Sys.getenv("KOA_NBOOT", "2000")); NC <- as.integer(Sys.getenv("KOA_CORES", "6")); POP <- 742
f <- readRDS("frames/frames.rds"); tr <- f$tr
th <- fread("~/jobs/koa_v105final_20261103/inputs/psp_origin_thinning_2026-09-16_DATA.csv"); REM <- th[removal_t1_years != "" & !is.na(removal_t1_years), .(yr = as.integer(unlist(strsplit(as.character(removal_t1_years), ";")))), by = .(Data, Install = as.character(Install))]
flagrem <- function(x, strict) { x <- copy(x); x[, rid__ := .I]; k <- merge(x[, .(rid__, Data, Install = as.character(Install), Measure, e_Measure)], REM, by = c("Data", "Install"), allow.cartesian = TRUE); k <- if (strict) k[yr > Measure & yr < e_Measure] else k[yr > Measure & yr <= e_Measure]; x[, rem__ := rid__ %in% k$rid__]; x }   # PSP thinning removals (psp_origin_thinning_2026-09-16_DATA.csv): mortality intervals ending in or spanning a removal year are censored; increment intervals with a removal year strictly inside are dropped
 cf0 <- koa_read_coef("release/koa_final_equations.csv"); Z <- readRDS("out/sdimax_byi.rds"); bgs <- Z$RF$s2_byi_origin$bg; bms <- Z$RF$s2_byi_origin$bm
J <- "~/jobs/koa_brms_sdimax_20261102/out/"; sx <- fread(paste0(J, "plot_sdimax_rilong.csv")); sx[, ID := as.character(ID)]
P <- unique(tr[, .(pid, Data, Install, Plot = as.character(Plot), planted, BYI)]); P[, key := ifelse(Data == "FIA", as.character(Install), pid)]
P <- merge(P, sx[, .(key = ID, ID1 = ID)], by = "key", all.x = TRUE); k2 <- sx[, .(Data, Plot = as.character(Plot), ID2 = ID)][, if (.N == 1) .SD, by = .(Data, Plot)]; P <- merge(P, k2, by = c("Data", "Plot"), all.x = TRUE); P[, ID := ifelse(!is.na(ID1), ID1, ID2)]
P <- merge(P, sx[, .(ID, smax = SDImax_mean, lo = `SDImax_q2.5`, hi = `SDImax_q97.5`)], by = "ID", all.x = TRUE); P[, `:=`(inst = paste(Data, Install), lbyi = log(BYI), ls = log(smax), w = 1 / pmax((log(hi) - log(lo)) / 3.92, 0.05)^2)]; P <- merge(P, make_folds(P), by = "inst"); M <- P[!is.na(smax)]
s1fit <- function(d) coef(lm(ls ~ lbyi + planted, data = d, weights = w)); s1p <- function(b, lbyi, pl) exp(b[[1]] + b[[2]] * lbyi + b[[3]] * pl); bs <- s1fit(M); stopifnot(max(abs(bs - Z$s2$byi_origin)) < 1e-8)
mS <- lm(ls ~ lbyi + planted, data = M, weights = w); rsd <- M$ls - fitted(mS); cat("(1) S1:", paste(names(bs), round(bs, 4), collapse = "; "), "; plots", nrow(M), "\nresidual of ln(plot SDImax) about S1: sd", round(sd(rsd), 3), "; weighted sd", round(sqrt(sum(M$w * rsd^2) / sum(M$w)), 3),
  "; 10th, 50th, 90th percentile natural:", round(quantile(rsd[M$planted == 0], c(.1, .5, .9)), 3), " planted:", round(quantile(rsd[M$planted == 1], c(.1, .5, .9)), 3), "\n")
SM <- setNames(s1p(bs, P$lbyi, P$planted), P$pid)
d <- flagrem(f$df[keep_fixed == TRUE], TRUE); cat("diameter increment frame: rows", nrow(d), "; dropped for a PSP removal year strictly inside the interval:", sum(d$rem__), "\n"); d <- d[rem__ == FALSE]; d[, `:=`(S0 = DBH, S1 = e_DBH)]; for (v in c("BAL", "BA_koa", "SDI_koa")) { e <- paste0("e_", v); d[is.na(get(e)), (e) := get(v)] }; d[, `:=`(sm = SM[pid], lbyi = log(BYI))]; stopifnot(!anyNA(d$sm)); d <- merge(d, P[, .(pid, fold_s = fold)], by = "pid")
xm <- function(S, BAL, BA, SDI, sm, byi, pl) cbind(1, log(S + 1), S, BAL / pmax(BA, 1e-6) * SDI / sm, log(byi), pl)
proj <- function(b, dd, sm = dd$sm) { S <- dd$S0; n <- dd$yip; acc <- numeric(nrow(dd)); for (t in seq_len(max(n))) { a <- t <= n; if (!any(a)) break; w <- (t - 1) / n[a]; iw <- function(v0, v1) (1 - w) * v0[a] + w * v1[a]
    g <- exp(xm(S[a], iw(dd$BAL, dd$e_BAL), iw(dd$BA_koa, dd$e_BA_koa), iw(dd$SDI_koa, dd$e_SDI_koa), sm[a], dd$BYI[a], dd$planted[a]) %*% b); S[a] <- S[a] + g; acc[a] <- acc[a] + g }; list(end = S, gbar = acc / n) }
fitg <- function(dd, b, sm = dd$sm, passes = 3) { w <- 1 / dd$yip; dl <- 0; conv <- NA; for (it in seq_len(passes)) { o <- optim(b, function(bb) sum(w * (dd$S1 - proj(bb, dd, sm)$end)^2), method = "BFGS", control = list(maxit = 500, reltol = 1e-10)); b <- o$par; conv <- o$convergence
    pr <- proj(b, dd, sm); r <- dd$S1 - pr$end; dl <- max(0, min(1.5, coef(lm(log(pmax(r^2 / dd$yip, 1e-8)) ~ log(pmax(pr$gbar, 0.01))))[[2]] / 2)); w <- 1 / (dd$yip * pmax(pr$gbar, 0.01)^(2 * dl)) }; list(b = setNames(b, names(bgs)), delta = dl, conv = conv) }
G <- fitg(d, bgs); bg <- G$b; cat("E4r, convergence", G$conv, " delta", round(G$delta, 4), "; largest change from the script 20 refit", signif(max(abs(bg - bgs)), 3), "\n"); print(round(bg, 5))
cv <- rbindlist(parallel::mclapply(sort(unique(d$fold_s)), function(k) { bk <- s1fit(M[fold != k]); trn <- d[fold_s != k]; te <- d[fold_s == k]; smt <- s1p(bk, trn$lbyi, trn$planted); sme <- s1p(bk, te$lbyi, te$planted); b <- fitg(trn, bg, smt)$b
  te2 <- copy(te); te2[, `:=`(e_BAL = BAL, e_BA_koa = BA_koa, e_SDI_koa = SDI_koa)]; data.table(pid = te$pid, planted = te$planted, obs = (te$S1 - te$S0) / te$yip, pred = (proj(b, te2, sme)$end - te$S0) / te$yip) }, mc.cores = 5))
cat("held-out installations (S1 and E4r both refitted in each fold; start-of-interval competition): annual diameter increment bias", round(mean(cv$obs - cv$pred), 4), " RMSE", round(sqrt(mean((cv$obs - cv$pred)^2)), 4), " (plot SDImax 1.132; 742 1.146)\n"); print(cbind(equiv_boot(cv$obs, cv$pred, cv$pid)[, .(slope = round(slope, 3), b1_lo = round(b1_lo, 3), b1_hi = round(b1_hi, 3), pass_int, pass_slope)]))
mf <- as.data.table(readRDS("frames/mf_confirmed.rds")); mf[, `:=`(ld = log(dbh_m + 1), lbyi = log(BYI))]; mf <- flagrem(mf, FALSE); cat("mortality frame: rows", nrow(mf), "deaths", sum(mf$died), "; censored as PSP removal intervals: rows", sum(mf$rem__), "deaths", sum(mf$died & mf$rem__), "; kept: rows", sum(!mf$rem__), "deaths", sum(mf$died & !mf$rem__), "\n"); mf <- mf[rem__ == FALSE]; mf[, sm := SM[pid]]; stopifnot(!anyNA(mf$sm)); y <- mf$died; off <- log(mf$yip)
XM <- function(sm, rows = seq_len(nrow(mf))) cbind(1, mf$ld[rows], mf$dbh_m[rows], mf$dbh_m[rows]^2, mf$BAL[rows], log(pmax(mf$SDI_koa[rows] / sm, 0.001)), mf$lbyi[rows], mf$planted[rows])
X0 <- XM(mf$sm); mu <- c(0, colMeans(X0[, -1])); sdv <- c(1, apply(X0[, -1], 2, sd)); toz <- function(b) { z <- b * sdv; z[1] <- b[1] + sum(b[-1] * mu[-1]); z }; fromz <- function(z) { b <- z / sdv; b[1] <- z[1] - sum(b[-1] * mu[-1]); b }
mlfit <- function(X, rows, z0) { Zm <- sweep(sweep(X, 2, mu), 2, sdv, "/"); Zm[, 1] <- 1; yy <- y[rows]; oo <- off[rows]
  nll <- function(z) { h <- exp(pmin(as.numeric(Zm %*% z) + oo, 30)); -sum(ifelse(yy == 1, log(-expm1(-h)), -h)) }; gr <- function(z) { h <- exp(pmin(as.numeric(Zm %*% z) + oo, 30)); -as.numeric(crossprod(Zm, ifelse(yy == 1, h * exp(-h) / (-expm1(-h)), -h))) }
  o <- nlminb(z0, nll, gr, control = list(iter.max = 1000, eval.max = 2000, rel.tol = 1e-12)); list(b = fromz(o$par), gmax = max(abs(gr(o$par))), nll = o$objective) }
F6 <- mlfit(X0, seq_len(nrow(mf)), toz(unname(bms))); bm <- setNames(F6$b, names(bms)); cat("E6r by direct likelihood: largest difference from the glm refit of script 20", signif(max(abs(bm - bms)), 3), "; largest gradient", signif(F6$gmax, 3), "; AIC", round(2 * F6$nll + 16, 1), "\n"); print(round(bm, 5))
cat("diameter of minimum mortality (cm):", round(uniroot(function(x) bm[["ld"]] / (x + 1) + bm[["dbh_m"]] + 2 * bm[["I(dbh_m^2)"]] * x, c(5, 300))$root, 1), "\n")
# (2) interval components
pr <- proj(bg, d); d[, `:=`(og = S1 - S0, pg = pr$end - S0, v = yip * pmax(pr$gbar, 0.01)^(2 * G$delta))]; pp <- d[, .(n = .N, R = sum(og) / sum(pg), sv = sum(v), sp = sum(pg)), by = pid][n >= 5]; d2 <- merge(d, pp[, .(pid, R)], by = "pid")
sigma2 <- sum((d2$og - d2$R * d2$pg)^2 / d2$v) / (nrow(d2) - nrow(pp)); tau2 <- max(0, var(pp$R) - mean(sigma2 * pp$sv / pp$sp^2)); mf[, p := 1 - exp(-exp(as.numeric(X0 %*% bm) + off))]; pmx <- mf[, .(D = sum(died), E = sum(p), V = sum(p * (1 - p))), by = pid]; phi <- max(0, sum((pmx$D - pmx$E)^2 - pmx$V) / sum(pmx$E^2))
cat("\n(2) interval components: sigma", round(sqrt(sigma2), 4), " tau", round(sqrt(tau2), 4), " delta", round(G$delta, 4), " phi", round(phi, 4), "\n")
saveRDS(list(bs = bs, bg = bg, bm = bm, delta = G$delta, sigma = sqrt(sigma2), tau = sqrt(tau2), phi = phi, s1_resid_sd = sd(rsd), s1_resid = data.table(planted = M$planted, r = rsd), cv = cv[, .(planted, obs, pred)]), "out/rdbyi2_fits.rds")
# (3) joint bootstrap
ipM <- split(seq_len(nrow(M)), M$pid); ipD <- split(seq_len(nrow(d)), d$pid); ipF <- split(seq_len(nrow(mf)), mf$pid); pn <- P$pid; RNGkind("L'Ecuyer-CMRG"); set.seed(20261117); z0 <- toz(unname(bm)); cat("\n(3) joint plot-cluster bootstrap,", NB, "resamples\n")
res <- parallel::mclapply(seq_len(NB), function(i) tryCatch({ s <- sample(pn, length(pn), TRUE); b1 <- s1fit(M[unlist(ipM[s], use.names = FALSE)]); rd <- unlist(ipD[s], use.names = FALSE); dd <- d[rd]; g <- fitg(dd, bg, s1p(b1, dd$lbyi, dd$planted))
  rf <- unlist(ipF[s], use.names = FALSE); m <- mlfit(XM(s1p(b1, mf$lbyi[rf], mf$planted[rf]), rf), rf, z0); c(b1, g$b, m$b, gconv = g$conv, gmax = m$gmax) }, error = function(e) rep(NA_real_, 19)), mc.cores = NC)
R <- do.call(rbind, res); colnames(R) <- c(paste0("s1_", names(bs)), paste0("e4_", names(bg)), paste0("e6_", names(bm)), "gconv", "gmax"); ok <- complete.cases(R) & R[, "gmax"] < 1e-2 & apply(abs(R[, 1:17]), 1, max) < 50
cat("resamples: errors", sum(!complete.cases(R)), "; E4r optim code not 0:", sum(R[, "gconv"] != 0, na.rm = TRUE), "; E6r gradient above 0.01:", sum(R[, "gmax"] >= 1e-2, na.rm = TRUE), "; kept", sum(ok), "\n"); K <- R[ok, 1:17]; est <- c(bs, bg, bm)
tab <- data.table(equation = rep(c("S1_sdimax", "E4r_diameter_increment", "E6r_mortality"), c(3, 6, 8)), term = sub("I\\(dbh_m\\^2\\)", "dbh_m2", c(names(bs), names(bg), names(bm))), estimate = unname(est), se_plot_bootstrap = apply(K, 2, sd), lo95 = apply(K, 2, quantile, .025), hi95 = apply(K, 2, quantile, .975), n_boot = nrow(K))
print(tab[, lapply(.SD, function(x) if (is.numeric(x)) signif(x, 5) else x)]); cat("share of kept resamples with: positive ln(BYI) in S1", round(mean(K[, "s1_lbyi"] > 0), 4), "; positive DBH-squared in E6r", round(mean(K[, "e6_I(dbh_m^2)"] > 0), 4), "; positive ln(RD) in E6r", round(mean(K[, "e6_lrd"] > 0), 4), "; negative competition term in E4r", round(mean(K[, "e4_xrd"] < 0), 4), "\n")
cat("SDImax from S1 with 95% bootstrap interval: natural at BYI 64, 248, 386:", paste(sapply(c(64, 248, 386), function(b) sprintf("%.0f (%.0f to %.0f)", s1p(bs, log(b), 0), quantile(exp(K[, 1] + K[, 2] * log(b)), .025), quantile(exp(K[, 1] + K[, 2] * log(b)), .975))), collapse = "; "),
    "\n  planted at BYI 120, 156, 230, 309, 340, 450:", paste(sapply(c(120, 156, 230, 309, 340, 450), function(b) sprintf("%.0f (%.0f to %.0f)", s1p(bs, log(b), 1), quantile(exp(K[, 1] + K[, 2] * log(b) + K[, 3]), .025), quantile(exp(K[, 1] + K[, 2] * log(b) + K[, 3]), .975))), collapse = "; "), "\n")
saveRDS(list(K = K, est = est, n = NB, kept = sum(ok)), "out/rdbyi2_boot.rds")
# (4) coefficient table and reference file
old <- fread("release/koa_final_equations.csv"); dir.create("release_rdbyi2", showWarnings = FALSE); fwrite(rbind(old[equation == "E2_height"], tab, fill = TRUE), "release_rdbyi2/koa_rdbyi_equations.csv")
e <- new.env(); sys.source("release_rdbyi2/koa_step_rdbyi.R", e); cr <- e$koa_read_coef("release_rdbyi2/koa_rdbyi_equations.csv"); L <- tr[pid == "PSP|111|11" & Measure == 2012 & Status == "live" & !is.na(DBH) & DBH > 0]; h0 <- koa_height(L$DBH, cf0); mxd <- 0
for (pl in c(0, 1)) for (by in c(64, 156, 386)) { a <- e$koa_project(L$DBH, h0, L$EXPF_c, by, pl, 200, cr); sm <- s1p(bs, log(by), pl); dbh <- L$DBH; ht <- h0; ex <- L$EXPF_c
  for (yy in 1:200) { s <- koa_stand(dbh, ht, ex); bal <- koa_bal(dbh, s$ba); g <- as.numeric(exp(xm(dbh, bal, s$BA, s$SDI, sm, by, pl) %*% bg)); pm <- 1 - exp(-exp(as.numeric(cbind(1, log(dbh + 1), dbh, dbh^2, bal, log(max(s$SDI / sm, 0.001)), log(by), pl) %*% bm))); ht <- ht + koa_height(dbh + g, cf0) - koa_height(dbh, cf0); dbh <- dbh + g; ex <- ex * (1 - pm) }
  s <- koa_stand(dbh, ht, ex); mxd <- max(mxd, abs(a$BA[201] - s$BA), abs(a$TPH[201] - s$TPH), abs(a$QMD[201] - s$QMD)) }
cat("\n(4) reference file against an independent loop from the fitted objects, six cases, year 200, largest absolute difference:", signif(mxd, 3), "\n"); stopifnot(mxd < 1e-6); cat("22t done\n")
